create function public.create_registration(p jsonb,p_code text,p_path text,p_size integer,p_actor uuid default null) returns uuid language plpgsql security definer set search_path=public as $$declare e seasons;pid uuid;rid uuid;begin
if p_actor is not null and not exists(select 1 from admin_profiles where user_id=p_actor and role in ('admin','super_admin')) then raise exception 'Unauthorized';end if;
perform set_config('app.actor',coalesce(p_actor::text,''),true);
select * into e from seasons where is_active for update;if e.id is null or now()<e.registration_open_at or now()>e.registration_close_at then raise exception 'Registration closed';end if;
if e.quota is not null and (select count(*) from registrations where season_id=e.id and registration_status not in ('cancelled','disqualified'))>=e.quota then raise exception 'Quota full';end if;
insert into participants(full_name,public_name,age,school_name,parent_name,whatsapp,instagram_username,address_line,province_code,province_name,regency_code,regency_name,district_code,district_name,village_code,village_name,postal_code) values(p->>'full_name',p->>'public_name',(p->>'age')::int,p->>'school_name',p->>'parent_name',p->>'whatsapp',p->>'instagram_username',p->>'address_line',p->>'province_code',p->>'province_name',p->>'regency_code',p->>'regency_name',p->>'district_code',p->>'district_name',p->>'village_code',p->>'village_name',p->>'postal_code') returning id into pid;
insert into registrations(season_id,participant_id,registration_code,competition_type,category,dream_job,class_label,registration_source,consent_parent_guardian,consent_publication,consent_terms,consent_fee) values(e.id,pid,p_code,p->>'competition_type',p->>'category',p->>'dream_job',p->>'class_label',case when p_actor is null then 'website' else coalesce(p->>'registration_source','admin_manual') end,(p->>'consent_parent_guardian')::boolean,(p->>'consent_publication')::boolean,(p->>'consent_terms')::boolean,(p->>'consent_fee')::boolean) returning id into rid;
insert into participant_media(registration_id,storage_path,mime_type,size_bytes) values(rid,p_path,'image/webp',p_size);
insert into payments(registration_id,payment_type,amount) values(rid,'registration',20000);return rid;end$$;
create function public.create_submission(p_code text,p_path text) returns uuid language plpgsql security definer set search_path=public as $$declare r registrations;e seasons;sid uuid;begin select * into r from registrations where registration_code=p_code for update;select * into e from seasons where id=r.season_id;if r.id is null or r.payment_status<>'paid' or r.registration_status<>'verified' or now()>least(r.created_at+interval '7 days',e.submission_global_close_at) then raise exception 'Submission unavailable';end if;insert into submissions(registration_id,submission_type,private_file_path) values(r.id,r.competition_type,p_path) returning id into sid;return sid;end$$;
create function public.admin_mutate(p_action text,p_id uuid,p_data jsonb) returns void language plpgsql security definer set search_path=public as $$declare role_name text;r registrations;s submissions;e seasons;v numeric;vals jsonb;begin
role_name:=admin_role();if role_name is null or (role_name='judge' and p_action<>'score') then raise exception 'Unauthorized';end if;
if p_action='score' then select * into s from submissions where id=p_id for update;if s.status<>'approved' then raise exception 'Not approved';end if;select * into r from registrations where id=s.registration_id;if exists(select 1 from results where registration_id=r.id and is_published) then raise exception 'Results locked';end if;vals:=p_data->'scores';if jsonb_array_length(vals)<>5 then raise exception 'Five scores required';end if;for i in 0..4 loop if (vals->>i)::numeric not between 0 and 100 then raise exception 'Invalid score';end if;end loop;v:=((vals->>0)::numeric*30+(vals->>1)::numeric*25+(vals->>2)::numeric*20+(vals->>3)::numeric*15+(vals->>4)::numeric*10)/100;insert into judging_scores(submission_id,judge_id,criteria,total_score,notes) values(p_id,auth.uid(),vals,v,p_data->>'notes') on conflict(submission_id,judge_id) do update set criteria=excluded.criteria,total_score=excluded.total_score,notes=excluded.notes,updated_at=now();return;
elsif p_action='settings' then if role_name<>'super_admin' then raise exception 'Super admin required';end if;update seasons set quota=nullif(p_data->>'quota','')::int,registration_open_at=(p_data->>'registration_open_at')::timestamptz,registration_close_at=(p_data->>'registration_close_at')::timestamptz,submission_global_close_at=(p_data->>'submission_global_close_at')::timestamptz,updated_at=now() where id=p_id;return;
elsif p_action in ('review','publish','unpublish') then select * into s from submissions where id=p_id for update;select * into r from registrations where id=s.registration_id for update;if s.id is null then raise exception 'Missing submission';end if;
if p_action='review' then if s.publication_status='approved' then raise exception 'Unpublish first';end if;if p_data->>'status' not in ('approved','revision_required','rejected') then raise exception 'Invalid review';end if;update submissions set status=p_data->>'status',review_note=p_data->>'note',reviewed_by=auth.uid(),reviewed_at=now(),updated_at=now() where id=p_id;
elsif p_action='publish' then if s.status<>'approved' or r.payment_status<>'paid' or r.registration_status<>'verified' or not r.consent_publication then raise exception 'Not publishable';end if;update submissions set publication_status='approved',public_file_path=p_data->>'path',updated_at=now() where id=p_id;
else update submissions set publication_status='hidden',public_file_path=null,updated_at=now() where id=p_id;end if;return;end if;
select * into r from registrations where id=p_id for update;if r.id is null then raise exception 'Missing registration';end if;select * into e from seasons where id=r.season_id;
if p_action='payment' then if p_data->>'status' not in ('pending','paid','rejected','refunded') then raise exception 'Invalid payment';end if;if p_data->>'status'<>'paid' and exists(select 1 from submissions where registration_id=r.id and publication_status='approved') then raise exception 'Unpublish first';end if;update payments set status=p_data->>'status',verified_by=auth.uid(),verified_at=now(),admin_note=p_data->>'note',updated_at=now() where registration_id=r.id and payment_type='registration';update registrations set payment_status=p_data->>'status',registration_status=case when p_data->>'status'='paid' then 'verified' else 'registered' end,updated_at=now() where id=r.id;
elsif p_action='worksheet' then if r.competition_type<>'coloring' or r.payment_status<>'paid' then raise exception 'Not eligible';end if;insert into worksheets(registration_id,private_file_path,version,created_by) select r.id,p_data->>'path',coalesce(max(version),0)+1,auth.uid() from worksheets where registration_id=r.id;
elsif p_action='award' then if r.payment_status<>'paid' then raise exception 'Not paid';end if;select avg(j.total_score) into v from judging_scores j join submissions sub on sub.id=j.submission_id where sub.registration_id=r.id and sub.status='approved';if v is null then raise exception 'Scores required';end if;insert into results(registration_id,final_score,award_code) values(r.id,round(v,2),p_data->>'award') on conflict(registration_id) do update set final_score=excluded.final_score,award_code=excluded.award_code,is_published=false,published_at=null,updated_at=now();
elsif p_action='result_publish' then if (p_data->>'published')::boolean and now()<e.announcement_at then raise exception 'Announcement not open';end if;update results set is_published=(p_data->>'published')::boolean,published_at=case when (p_data->>'published')::boolean then now() end,updated_at=now() where registration_id=r.id;
elsif p_action='invoice' then if not exists(select 1 from results where registration_id=r.id and is_published) or now()<e.announcement_at then raise exception 'Results not published';end if;insert into claim_invoices(registration_id,invoice_number) values(r.id,'INV-'||upper(replace(gen_random_uuid()::text,'-',''))) on conflict(registration_id) do nothing;insert into payments(registration_id,payment_type,amount) values(r.id,'award_claim',120000) on conflict(registration_id,payment_type) do nothing;
elsif p_action='claim_paid' then if not exists(select 1 from claim_invoices where registration_id=r.id and status='issued') then raise exception 'Invoice required';end if;update claim_invoices set status='paid',paid_at=now() where registration_id=r.id;update payments set status='paid',verified_by=auth.uid(),verified_at=now() where registration_id=r.id and payment_type='award_claim';
elsif p_action='shipment' then if not exists(select 1 from claim_invoices where registration_id=r.id and status='paid') then raise exception 'Paid claim required';end if;if p_data->>'status' in ('shipped','delivered') and (now()<e.shipping_at or coalesce(p_data->>'tracking','')='') then raise exception 'Shipping date or tracking invalid';end if;insert into shipments(registration_id,courier,tracking_number,shipping_status,shipped_at,delivered_at) values(r.id,p_data->>'courier',p_data->>'tracking',p_data->>'status',case when p_data->>'status' in ('shipped','delivered') then now() end,case when p_data->>'status'='delivered' then now() end) on conflict(registration_id) do update set courier=excluded.courier,tracking_number=excluded.tracking_number,shipping_status=excluded.shipping_status,shipped_at=coalesce(shipments.shipped_at,excluded.shipped_at),delivered_at=excluded.delivered_at,updated_at=now();
else raise exception 'Unknown action';end if;end$$;
revoke all on function create_registration(jsonb,text,text,integer,uuid),create_submission(text,text) from public,anon,authenticated;
grant execute on function create_registration(jsonb,text,text,integer,uuid),create_submission(text,text) to service_role;
revoke all on function admin_mutate(text,uuid,jsonb) from public,anon;grant execute on function admin_mutate(text,uuid,jsonb) to authenticated;
